                ">=" -> T_ge (SLoc (row1, col1) (row2, col2))
                "=" -> T_eq (SLoc (row1, col1) (row2, col2))
                "<" -> T_lt (SLoc (row1, col1) (row2, col2))
                ">" -> T_gt (SLoc (row1, col1) (row2, col2))
