            ((51, this), ((row1, col1), (row2, col2))) -> return_one (mkCharToken (SLoc (row1, col1) (row2, col2)) this)
            ((52, this), ((row1, col1), (row2, col2))) -> return []
            ((53, this), ((row1, col1), (row2, col2))) -> return []
            ((54, this), ((row1, col1), (row2, col2))) -> return []
